WITH scored AS (SELECT id, store_id, product_id, quantity, SUM(quantity) OVER w_hist AS running_sum_quantity, COUNT(quantity) OVER w_hist AS running_count_quantity, AVG(quantity) OVER w_hist AS running_avg_quantity FROM inventory WINDOW w_hist AS (PARTITION BY store_id ORDER BY quantity, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)) SELECT id, store_id, product_id, quantity, running_sum_quantity FROM scored ORDER BY id
